import pygameimport osBASE_IMG_PATH = 'data/images/'def load_image(path, rotate=0, scale=1):    img = pygame.image.load(BASE_IMG_PATH + path)    img = pygame.transform.rotozoom(img, rotate, scale)    return imgdef load_images(path, img_type='.png', rotate=0, scale=1):    frames = []    file_list = sorted(os.listdir(BASE_IMG_PATH + path))    if img_type:        file_list = [f for f in file_list if img_type in f]    for file in file_list:         frames.append(load_image(path + '/' + file, rotate, scale))    return framesclass Animation:    def __init__(self, images, img_dur=5, loop=True):        self.images = images        self.loop = loop        self.img_duration = img_dur        self.done = False        self.frame = 0        def max_dims(self):        widths = []        heights = []        for img in self.images:            widths.append(img.get_width())            heights.append(img.get_height())                return [max(widths), max(heights)]            def copy(self):        return Animation(self.images, self.img_duration, self.loop)        def update(self):        if self.loop:            # loop frames in animation when it reaches max n frames            self.frame = (self.frame + 1) % (self.img_duration * len(self.images))        else:            self.frame = min(self.frame + 1, self.img_duration * len(self.images) - 1)            if self.frame >= self.img_duration * len(self.images) - 1:                self.done = True                    def img(self):        return self.images[int(self.frame / self.img_duration)]        